SELECT id, tenant_id AS tenantId, task_name AS taskName, business_type AS businessType, status, started_at AS startedAt, finished_at AS finishedAt, created_at AS createdAt FROM marketing_task WHERE deleted_at IS NULL AND id IN
#{taskId}
ORDER BY FIELD(id,
#{taskId}
)

SELECT 
FROM marketing_task_export_job
WHERE id = #{id}
  AND created_by = #{createdBy}

SELECT 
FROM marketing_task_export_job
WHERE tenant_id = #{tenantId}
  AND created_by = #{createdBy}
  AND request_hash = #{requestHash}
  AND status IN ('PENDING', 'PROCESSING')
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE marketing_task_export_job
SET storage_key = NULL,
    content_type = NULL,
    file_size = NULL,
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'SUCCESS'
  AND expires_at <= #{now}
  AND storage_key = #{storageKey}

UPDATE marketing_task_export_job
SET lease_until = #{leaseUntil},
    updated_at = #{now}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'PROCESSING'
  AND claim_token = #{claimToken}

UPDATE marketing_task_export_job
SET status = 'FAILED',
    error_message = #{errorMessage},
    lease_until = NULL,
    claim_token = NULL,
    finished_at = #{finishedAt},
    updated_at = #{finishedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND status = 'PROCESSING'
  AND claim_token = #{claimToken}

mapper.select:
WITH successful_marketing_source AS ( SELECT a.id AS attempt_id, a.tenant_id, a.marketing_task_id, TRIM(a.group_jid) AS group_jid, a.group_link_id, NULLIF(TRIM(a.group_name), '') AS group_name, t.account_id AS sender_account_id, NULLIF(TRIM(t.account_phone), '') AS sender_phone, COALESCE(a.result_at, a.attempted_at, a.created_at) AS event_at FROM marketing_task_send_attempt a JOIN marketing_task_target t ON t.id = a.target_id AND t.marketing_task_id = a.marketing_task_id AND t.tenant_id = a.tenant_id WHERE a.tenant_id = #{tenantId} AND a.status = 1 AND a.group_jid IS NOT NULL AND TRIM(a.group_jid) <> '' AND ((a.result_at IS NOT NULL AND a.result_at <= #{snapshotAt}) OR (a.result_at IS NULL AND a.submitted_at IS NULL AND COALESCE(a.attempted_at, a.created_at) <= #{snapshotAt})) AND a.marketing_task_id IN
#{taskId}
), successful_marketing AS ( SELECT ranked.* FROM ( SELECT source.*, ROW_NUMBER() OVER ( PARTITION BY tenant_id, marketing_task_id, group_jid ORDER BY event_at DESC, attempt_id DESC) AS sender_rank, COUNT(*) OVER ( PARTITION BY tenant_id, marketing_task_id, group_jid) AS marketing_count FROM successful_marketing_source source ) ranked WHERE ranked.sender_rank = 1 ), group_status_source AS ( SELECT a.id AS attempt_id, a.tenant_id, a.marketing_task_id, COALESCE(NULLIF(TRIM(a.group_jid), ''), NULLIF(TRIM(t.group_jid), '')) AS group_jid, a.status AS projected_status, a.reason_code, a.group_status, a.group_status_reason, a.round_no, a.attempt_no, CASE WHEN a.status = 1 THEN 1 WHEN a.status = 2 AND ( UPPER(TRIM(COALESCE(a.group_status, ''))) IN ('NORMAL', 'BANNED', 'NO_PERMISSION') OR UPPER(TRIM(COALESCE(a.reason_code, ''))) IN ( 'ACCOUNT_BANNED', 'KICKED_OUT', 'ACCOUNT_NOT_PARTICIPANT', 'GROUP_BANNED', 'BANNED', 'CHAT_SUSPENDED', 'CHAT_TERMINATED', 'NO_PERMISSION', 'ANNOUNCE_ONLY_NON_ADMIN') OR UPPER(TRIM(COALESCE(a.group_status_reason, ''))) IN ( 'GROUP_SEND_ALLOWED', 'ACCOUNT_NOT_PARTICIPANT', 'CHAT_SUSPENDED', 'CHAT_TERMINATED', 'ANNOUNCE_ONLY_NON_ADMIN')) THEN 1 ELSE 0 END AS effective_group_status FROM marketing_task_send_attempt a JOIN marketing_task_target t ON t.id = a.target_id AND t.marketing_task_id = a.marketing_task_id AND t.tenant_id = a.tenant_id WHERE a.tenant_id = #{tenantId} AND a.status IN (1, 2) AND COALESCE(NULLIF(TRIM(a.group_jid), ''), NULLIF(TRIM(t.group_jid), '')) IS NOT NULL AND ((a.result_at IS NOT NULL AND a.result_at <= #{snapshotAt}) OR (a.result_at IS NULL AND a.submitted_at IS NULL AND COALESCE(a.attempted_at, a.created_at) <= #{snapshotAt})) AND a.marketing_task_id IN
#{taskId}
), latest_group_status AS ( SELECT ranked.* FROM ( SELECT source.*, ROW_NUMBER() OVER ( PARTITION BY tenant_id, marketing_task_id, group_jid ORDER BY effective_group_status DESC, round_no DESC, attempt_no DESC, attempt_id DESC) AS status_rank FROM group_status_source source ) ranked WHERE ranked.status_rank = 1 ) SELECT MIN(COALESCE(jtr.joined_at, jtr.updated_at, jtr.created_at)) AS joinedAt, mt.id AS taskId, mt.task_name AS taskName, REGEXP_REPLACE( COALESCE(NULLIF(TRIM(joined_account.ws_phone), ''), NULLIF(TRIM(jtr.account), '')), '[^0-9]', '') AS actualPhone, COALESCE(sm.group_name, NULLIF(TRIM(preview.wa_subject), ''), sm.group_jid) AS groupName, group_link_data.link_url AS groupLink, AS groupStatus, CASE WHEN preview.announce_only = 1 AND membership.is_admin = 1 THEN '仅管理员可发言（发送账号可发言）' WHEN preview.announce_only = 1 THEN '无发言权限' WHEN preview.announce_only = 0 THEN '所有成员可发言' ELSE '未确认' END AS speechPermission, sm.sender_phone AS senderPhone, sm.marketing_count AS marketingCount FROM successful_marketing sm JOIN marketing_task mt ON mt.id = sm.marketing_task_id AND mt.tenant_id = sm.tenant_id AND mt.business_type = 1 AND mt.deleted_at IS NULL JOIN join_task_result jtr ON jtr.group_jid = sm.group_jid AND jtr.tenant_id = sm.tenant_id AND jtr.status = 'SUCCESS' AND COALESCE(jtr.joined_at, jtr.updated_at, jtr.created_at) <= #{snapshotAt} LEFT JOIN account joined_account ON joined_account.id = jtr.account_id AND joined_account.tenant_id = jtr.tenant_id AND joined_account.deleted_at IS NULL LEFT JOIN group_link_preview preview ON preview.group_link_id = sm.group_link_id AND preview.tenant_id = sm.tenant_id AND (preview.group_jid IS NULL OR preview.group_jid = sm.group_jid) LEFT JOIN group_link_health health ON health.group_link_id = sm.group_link_id AND health.tenant_id = sm.tenant_id LEFT JOIN group_link group_link_data ON group_link_data.id = sm.group_link_id AND group_link_data.tenant_id = sm.tenant_id LEFT JOIN latest_group_status protocol ON protocol.tenant_id = sm.tenant_id AND protocol.marketing_task_id = sm.marketing_task_id AND protocol.group_jid = sm.group_jid LEFT JOIN account_group_membership membership ON membership.tenant_id = sm.tenant_id AND membership.account_id = sm.sender_account_id AND membership.group_jid = sm.group_jid AND membership.deleted_at IS NULL GROUP BY mt.id, mt.task_name, REGEXP_REPLACE( COALESCE(NULLIF(TRIM(joined_account.ws_phone), ''), NULLIF(TRIM(jtr.account), '')), '[^0-9]', ''), sm.group_jid, sm.group_name, preview.wa_subject, group_link_data.link_url, health.is_banned, health.health_status, protocol.projected_status, protocol.reason_code, protocol.group_status, protocol.group_status_reason, preview.announce_only, membership.is_admin, sm.sender_phone, sm.marketing_count HAVING actualPhone IS NOT NULL AND actualPhone <> '' ORDER BY mt.id ASC, sm.group_jid ASC, actualPhone ASC
